    ns.write("/Automation/lib/shared.js", "/** @param {NS} ns */\n\nconst FACTION_FILE = \"/Automation/state/factions.json\";\n\n/** @returns {boolean} */\nexport function singularityReady(ns) {\n    try {\n        ns.singularity.getOwnedSourceFiles();\n        return true;\n    } catch {\n        return false;\n    }\n}\n\n/** @returns {number} 0 if unavailable */\nexport function sfLevel(ns, n) {\n    try {\n        for (const sf of ns.singularity.getOwnedSourceFiles()) {\n            if (sf.n === n) return sf.lvl;\n        }\n    } catch {\n        /* unavailable */\n    }\n    return 0;\n}\n\n/** @returns {boolean} */\nexport function hasSf(ns, n, min = 1) {\n    return sfLevel(ns, n) >= min;\n}\n\n/** SF4 singularity API RAM multiplier (16 / 4 / 1). */\nexport function singularityRamMult(ns) {\n    const lvl = sfLevel(ns, 4);\n    if (lvl >= 3) return 1;\n    if (lvl >= 2) return 4;\n    return 16;\n}\n\nexport function budget(ns, reservePct = 0.15, minReserve = 1e6) {\n    const money = ns.getServerMoneyAvailable(\"home\");\n    return money - Math.max(minReserve, money * reservePct);\n}\n\nexport function crawl(ns) {\n    const seen = new Set([\"home\"]);\n    const queue = [\"home\"];\n    const out = [];\n    while (queue.length > 0) {\n        const host = queue.shift();\n        for (const n of ns.scan(host)) {\n            if (!seen.has(n)) {\n                seen.add(n);\n                queue.push(n);\n                out.push(n);\n            }\n        }\n    }\n    return out;\n}\n\nexport function isHacknetServer(host) {\n    return host.startsWith(\"hacknet-server-\");\n}\n\nexport function loadFactions(ns) {\n    if (!ns.fileExists(FACTION_FILE, \"home\")) return [];\n    try {\n        const raw = ns.read(FACTION_FILE);\n        const parsed = JSON.parse(raw);\n        return Array.isArray(parsed) ? parsed : [];\n    } catch {\n        return [];\n    }\n}\n\nexport function rememberFaction(ns, name) {\n    const set = new Set(loadFactions(ns));\n    set.add(name);\n    ns.write(FACTION_FILE, JSON.stringify([...set]), \"w\");\n}\n\nexport function findPath(ns, from, to) {\n    if (from === to) return [from];\n    const seen = new Set([from]);\n    const queue = [[from, [from]]];\n    while (queue.length > 0) {\n        const [node, path] = queue.shift();\n        for (const n of ns.scan(node)) {\n            if (seen.has(n)) continue;\n            seen.add(n);\n            const next = [...path, n];\n            if (n === to) return next;\n            queue.push([n, next]);\n        }\n    }\n    return null;\n}\n\n/** Walk the network from the current server to `target`. */\nexport function connectTo(ns, target) {\n    if (!singularityReady(ns)) return false;\n    const start = ns.singularity.getCurrentServer();\n    if (start === target) return true;\n\n    const path = findPath(ns, start, target);\n    if (!path) return false;\n\n    for (let i = 1; i < path.length; i++) {\n        if (!ns.singularity.connect(path[i])) return false;\n    }\n    return ns.singularity.getCurrentServer() === target;\n}\n\nexport function goHome(ns) {\n    return connectTo(ns, \"home\");\n}\n\nexport const ALL_FACTIONS = [\n    \"CyberSec\", \"Netburners\", \"Tian Di Hui\", \"Sector-12\", \"Chongqing\", \"New Tokyo\",\n    \"Volhaven\", \"Aevum\", \"Slum Snakes\", \"Tetrads\", \"Silhouette\", \"Speakers for the Dead\",\n    \"The Dark Army\", \"The Syndicate\", \"NiteSec\", \"The Black Hand\", \"BitRunners\",\n    \"ECorp\", \"MegaCorp\", \"Bachman & Associates\", \"Blade Industries\", \"NWO\",\n    \"Clarke Incorporated\", \"OmniTek Incorporated\", \"Four Sigma\", \"KuaiGong International\",\n    \"Fulcrum Secret Technologies\", \"The Covenant\", \"Illuminati\", \"Daedalus\",\n    \"Bladeburners\", \"Church of the Machine God\",\n];\n\nexport function memberFactions(ns) {\n    const remembered = new Set(loadFactions(ns));\n    if (!singularityReady(ns)) return [...remembered];\n\n    for (const faction of ALL_FACTIONS) {\n        try {\n            const rep = ns.singularity.getFactionRep(faction);\n            const favor = ns.singularity.getFactionFavor(faction);\n            if (rep > 0 || favor > 0) remembered.add(faction);\n        } catch {\n            /* not a member */\n        }\n    }\n    return [...remembered];\n}", "w");
    ns.tprint("  /Automation/lib/shared.js");
    ns.write("/Automation/modules/augments.js", "/** @param {NS} ns */\n// Purchase the best affordable augmentation from joined factions.\n\nimport { budget, memberFactions, singularityReady } from \"/Automation/lib/shared.js\";\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n\n    const money = budget(ns, 0.25, 5e6);\n    if (money <= 0) return;\n\n    const owned = new Set(ns.singularity.getOwnedAugmentations());\n    const purchased = new Set(ns.singularity.getOwnedAugmentations(true));\n    let best = null;\n\n    for (const faction of memberFactions(ns)) {\n        for (const aug of ns.singularity.getAugmentationsFromFaction(faction)) {\n            if (aug === \"NeuroFlux Governor\") continue;\n            if (owned.has(aug) || purchased.has(aug)) continue;\n            if (!prereqsMet(ns, aug, owned, purchased)) continue;\n\n            const rep = ns.singularity.getFactionRep(faction);\n            if (rep < ns.singularity.getAugmentationRepReq(aug)) continue;\n\n            const price = ns.singularity.getAugmentationPrice(aug);\n            if (price > money) continue;\n\n            const stats = ns.singularity.getAugmentationStats(aug);\n            const score = augValue(stats) / price;\n            if (!best || score > best.score) {\n                best = { faction, aug, score };\n            }\n        }\n    }\n\n    if (best) ns.singularity.purchaseAugmentation(best.faction, best.aug);\n}\n\nfunction prereqsMet(ns, aug, owned, purchased) {\n    for (const req of ns.singularity.getAugmentationPrereq(aug)) {\n        if (!owned.has(req) && !purchased.has(req)) return false;\n    }\n    return true;\n}\n\nfunction augValue(stats) {\n    return (stats.hacking ?? 1) *\n        (stats.hacking_exp ?? 1) *\n        (stats.hacking_chance ?? 1) *\n        (stats.hacking_speed ?? 1) *\n        (stats.hacking_money ?? 1) *\n        (stats.faction_rep ?? 1) *\n        (stats.faction_work ?? 1);\n}", "w");
    ns.tprint("  /Automation/modules/augments.js");
    ns.write("/Automation/modules/backdoor.js", "/** @param {NS} ns */\n// Install backdoors on faction / endgame servers when rooted and reachable.\n\nimport { connectTo, goHome, singularityReady } from \"/Automation/lib/shared.js\";\n\n/** Priority-ordered servers worth backdooring. */\nconst TARGETS = [\n    { host: \"CSEC\", minHack: 1 },\n    { host: \"avmniteohdf-8hd\", minHack: 1 },\n    { host: \"run4theh111z\", minHack: 1 },\n    { host: \"The-Cave\", minHack: 1 },\n    { host: \"I.I.I.I\", minHack: 1 },\n    { host: \"w0r1d_d43m0n\", minHack: 3000 },\n];\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n\n    const hack = ns.getHackingLevel();\n    if (!goHome(ns)) return;\n\n    for (const { host, minHack } of TARGETS) {\n        if (hack < minHack) continue;\n        if (!ns.serverExists(host)) continue;\n        if (!ns.hasRootAccess(host)) continue;\n\n        const srv = ns.getServer(host);\n        if (srv.backdoorInstalled) continue;\n        if (ns.getServerRequiredHackingLevel(host) > hack) continue;\n\n        if (!connectTo(ns, host)) continue;\n\n        await ns.singularity.installBackdoor();\n        goHome(ns);\n        return;\n    }\n}", "w");
    ns.tprint("  /Automation/modules/backdoor.js");
    ns.write("/Automation/modules/contracts.js", "/** @param {NS} ns */\n// Find and solve coding contracts on rooted servers.\n\nimport { crawl } from \"/Automation/lib/shared.js\";\nimport { solveContract } from \"/Automation/lib/contractSolver.js\";\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n\n    const hosts = [\"home\", ...crawl(ns)];\n    for (const host of hosts) {\n        if (!ns.hasRootAccess(host)) continue;\n        const files = ns.ls(host, \".cct\");\n        for (const file of files) {\n            const tries = ns.codingcontract.getNumTriesRemaining(file, host);\n            if (tries <= 0) continue;\n\n            const type = ns.codingcontract.getContractType(file, host);\n            const data = ns.codingcontract.getData(file, host);\n            const answer = solveContract(type, data);\n            if (answer == null) continue;\n\n            const reward = ns.codingcontract.attempt(answer, file, host);\n            if (reward) return;\n        }\n    }\n}", "w");
    ns.tprint("  /Automation/modules/contracts.js");
    ns.write("/Automation/modules/create.js", "/** @param {NS} ns */\n// Create programs locally when hacking level allows and they are missing.\n\nimport { singularityReady } from \"/Automation/lib/shared.js\";\n\nconst CREATE_ORDER = [\n    \"BruteSSH.exe\",\n    \"FTPCrack.exe\",\n    \"relaySMTP.exe\",\n    \"HTTPWorm.exe\",\n    \"SQLInject.exe\",\n    \"Formulas.exe\",\n    \"AutoLink.exe\",\n    \"ServerProfiler.exe\",\n    \"DeepscanV1.exe\",\n    \"DeepscanV2.exe\",\n    \"DeepscanV3.exe\",\n];\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n\n    const work = ns.singularity.getCurrentWork();\n    if (work && work.type === \"CREATE_PROGRAM\") return;\n\n    const hack = ns.getHackingLevel();\n    for (const program of CREATE_ORDER) {\n        if (ns.fileExists(program, \"home\")) continue;\n        const need = ns.singularity.getHackingLevelRequirementOfProgram(program);\n        if (need > hack) continue;\n        if (ns.singularity.createProgram(program, false)) return;\n    }\n}", "w");
    ns.tprint("  /Automation/modules/create.js");
    ns.write("/Automation/modules/factions.js", "/** @param {NS} ns */\n// Accept all outstanding faction invitations.\n\nimport { rememberFaction, singularityReady } from \"/Automation/lib/shared.js\";\n\nconst SKIP = new Set([\n    \"Shadows of Anarchy\",\n]);\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n\n    const invites = ns.singularity.checkFactionInvitations();\n    for (const faction of invites) {\n        if (SKIP.has(faction)) continue;\n        if (ns.singularity.joinFaction(faction)) {\n            rememberFaction(ns, faction);\n            return;\n        }\n    }\n}", "w");
    ns.tprint("  /Automation/modules/factions.js");
    ns.write("/Automation/modules/grafting.js", "/** @param {NS} ns */\n// Graft augmentations (SF10+) without a full reset.\n\nimport { budget, hasSf, singularityReady } from \"/Automation/lib/shared.js\";\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n    if (!hasSf(ns, 10, 1)) return;\n\n    const work = ns.singularity.getCurrentWork();\n    if (work && work.type === \"GRAFTING\") return;\n\n    const money = budget(ns, 0.3, 1e8);\n    if (money <= 0) return;\n\n    const owned = new Set(ns.singularity.getOwnedAugmentations());\n    let best = null;\n\n    for (const aug of ns.grafting.getGraftableAugmentations()) {\n        if (owned.has(aug)) continue;\n        if (!prereqsMet(ns, aug, owned)) continue;\n\n        const price = ns.grafting.getAugmentationGraftPrice(aug);\n        if (!Number.isFinite(price) || price <= 0 || price > money) continue;\n\n        const stats = ns.singularity.getAugmentationStats(aug);\n        const score = augValue(stats) / price;\n        if (!best || score > best.score) best = { aug, score };\n    }\n\n    if (!best) return;\n\n    if (ns.singularity.getCurrentServer() !== \"New Tokyo\") {\n        ns.singularity.travelToCity(\"New Tokyo\");\n    }\n\n    ns.grafting.graftAugmentation(best.aug, false);\n}\n\nfunction prereqsMet(ns, aug, owned) {\n    for (const req of ns.singularity.getAugmentationPrereq(aug)) {\n        if (!owned.has(req)) return false;\n    }\n    return true;\n}\n\nfunction augValue(stats) {\n    return (stats.hacking ?? 1) *\n        (stats.hacking_exp ?? 1) *\n        (stats.hacking_chance ?? 1) *\n        (stats.hacking_speed ?? 1) *\n        (stats.hacking_money ?? 1);\n}", "w");
    ns.tprint("  /Automation/modules/grafting.js");
    ns.write("/Automation/modules/hack.js", "/** @param {NS} ns */\n// ═══════════════════════════════════════════════════════════════════════════════\n// Hack Module — HWGW shotgun batcher + target prep\n// ═══════════════════════════════════════════════════════════════════════════════\n// Long-running daemon launched by brain.js. Uses /Automation/workers/* on the\n// shared worker pool (home, cloud, hacknet, rooted world servers).\n// ═══════════════════════════════════════════════════════════════════════════════\n\nconst ROOT = \"/Automation\";\n\nconst CFG = {\n    maxTargets: 15,\n    hackPct: 0.25,\n    secThresh: 5,\n    moneyThresh: 0.75,\n    workerH: `${ROOT}/workers/hack.js`,\n    workerG: `${ROOT}/workers/grow.js`,\n    workerW: `${ROOT}/workers/weaken.js`,\n    spacing: 25,\n    maxBatchesPerTgt: 500,\n    maxTotalBatches: 5000,\n    loopMs: 2000,\n    scanEvery: 15,\n    statusEvery: 6,\n};\n\nconst CRACKERS = [\n    [\"BruteSSH.exe\", \"brutessh\"],\n    [\"FTPCrack.exe\", \"ftpcrack\"],\n    [\"relaySMTP.exe\", \"relaysmtp\"],\n    [\"HTTPWorm.exe\", \"httpworm\"],\n    [\"SQLInject.exe\", \"sqlinject\"],\n];\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    ns.clearLog();\n    ns.ui.openTail();\n\n    const S = {\n        hosts: [],\n        rooted: [],\n        cloud: new Set(),\n        targets: [],\n        tick: 0,\n        hasFormulas: false,\n        batchesLast: 0,\n    };\n\n    while (true) {\n        S.tick++;\n\n        if (S.tick === 1 || S.tick % CFG.scanEvery === 1) {\n            refreshNetwork(ns, S);\n            S.hasFormulas = ns.fileExists(\"Formulas.exe\", \"home\");\n        }\n\n        deployHacking(ns, S);\n\n        if (S.tick % CFG.statusEvery === 0) showStatus(ns, S);\n\n        await ns.sleep(CFG.loopMs);\n    }\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// NETWORK\n// ═══════════════════════════════════════════════════════════════════════════════\n\nfunction isHacknetServer(host) {\n    return host.startsWith(\"hacknet-server-\");\n}\n\nfunction refreshNetwork(ns, S) {\n    S.cloud = new Set(ns.cloud.getServerNames());\n    S.hosts = crawl(ns);\n    S.rooted = [\"home\"];\n\n    const crackers = CRACKERS.filter(([exe]) => ns.fileExists(exe, \"home\"));\n\n    for (const host of S.hosts) {\n        if (isHacknetServer(host)) {\n            S.rooted.push(host);\n            continue;\n        }\n\n        if (!ns.hasRootAccess(host)) {\n            if (ns.getServerRequiredHackingLevel(host) > ns.getHackingLevel()) continue;\n            if (ns.getServerNumPortsRequired(host) > crackers.length) continue;\n            for (const [, api] of crackers) ns[api](host);\n            ns.nuke(host);\n        }\n\n        if (ns.hasRootAccess(host)) S.rooted.push(host);\n    }\n}\n\nfunction crawl(ns) {\n    const seen = new Set([\"home\"]);\n    const queue = [\"home\"];\n    const out = [];\n    while (queue.length > 0) {\n        const host = queue.shift();\n        for (const n of ns.scan(host)) {\n            if (!seen.has(n)) {\n                seen.add(n);\n                queue.push(n);\n                out.push(n);\n            }\n        }\n    }\n    return out;\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// TARGET SCORING\n// ═══════════════════════════════════════════════════════════════════════════════\n\nfunction scoreTarget(ns, host, hasFormulas) {\n    if (host === \"home\" || isHacknetServer(host)) return 0;\n    const maxMoney = ns.getServerMaxMoney(host);\n    if (maxMoney === 0) return 0;\n    if (ns.getServerRequiredHackingLevel(host) > ns.getHackingLevel()) return 0;\n\n    if (hasFormulas) {\n        try {\n            const srv = ns.getServer(host);\n            const player = ns.getPlayer();\n            srv.hackDifficulty = srv.minDifficulty;\n            srv.moneyAvailable = srv.moneyMax;\n            const chance = ns.formulas.hacking.hackChance(srv, player);\n            const pct = ns.formulas.hacking.hackPercent(srv, player);\n            const time = ns.formulas.hacking.hackTime(srv, player) / 1000;\n            if (chance <= 0 || pct <= 0 || time <= 0) return 0;\n            return (chance * pct * maxMoney) / time;\n        } catch {\n            /* fallback */\n        }\n    }\n\n    const minSec = ns.getServerMinSecurityLevel(host);\n    const growth = ns.getServerGrowth(host);\n    const diff = Math.max(0.1, ns.getServerRequiredHackingLevel(host) / ns.getHackingLevel());\n    return (maxMoney / 1e6) * (growth / 100) / Math.max(1, minSec) / diff;\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// WORKER POOL\n// ═══════════════════════════════════════════════════════════════════════════════\n\nfunction getWorkerPool(ns, S) {\n    const world = [], cloud = [];\n    let homeEntry = null;\n    const seen = new Set();\n\n    for (const host of [\"home\", ...S.rooted]) {\n        if (seen.has(host)) continue;\n        seen.add(host);\n\n        const max = ns.getServerMaxRam(host);\n        if (max < 2) continue;\n        const free = max - ns.getServerUsedRam(host);\n        if (free < 1.75) continue;\n\n        const entry = { host, free };\n        if (host === \"home\") homeEntry = entry;\n        else if (S.cloud.has(host) || isHacknetServer(host)) cloud.push(entry);\n        else world.push(entry);\n    }\n\n    const pool = [...world, ...cloud];\n    if (homeEntry) pool.push(homeEntry);\n    return pool;\n}\n\nfunction spawnAcross(ns, script, target, threads, pool, delay) {\n    const ramPer = ns.getScriptRam(script, \"home\");\n    if (ramPer <= 0 || threads <= 0) return 0;\n\n    let remaining = threads;\n    for (const w of pool) {\n        if (remaining <= 0) break;\n        const canRun = Math.floor(w.free / ramPer);\n        if (canRun <= 0) continue;\n        const t = Math.min(canRun, remaining);\n        if (ns.exec(script, w.host, t, target, delay || 0) > 0) {\n            w.free -= t * ramPer;\n            remaining -= t;\n        }\n    }\n    return threads - remaining;\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// HWGW BATCH CALCULATOR\n// ═══════════════════════════════════════════════════════════════════════════════\n\nfunction calcBatch(ns, host, hackPct, hasFormulas) {\n    let hackTime, growTime, weakenTime, hThreads, gThreads;\n\n    if (hasFormulas) {\n        try {\n            const srv = ns.getServer(host);\n            const player = ns.getPlayer();\n            const cores = ns.getServer(\"home\").cpuCores;\n            srv.hackDifficulty = srv.minDifficulty;\n            srv.moneyAvailable = srv.moneyMax;\n\n            hackTime = ns.formulas.hacking.hackTime(srv, player);\n            growTime = ns.formulas.hacking.growTime(srv, player);\n            weakenTime = ns.formulas.hacking.weakenTime(srv, player);\n\n            const hackPerThread = ns.formulas.hacking.hackPercent(srv, player);\n            if (hackPerThread <= 0) return null;\n            hThreads = Math.max(1, Math.floor(hackPct / hackPerThread));\n            const stolen = Math.min(0.99, hackPerThread * hThreads);\n            const growRatio = 1 / (1 - stolen);\n\n            srv.moneyAvailable = srv.moneyMax * (1 - stolen);\n            gThreads = 1;\n            while (gThreads < 5000) {\n                const mult = ns.formulas.hacking.growPercent(srv, gThreads, player, cores);\n                if (mult >= growRatio) break;\n                gThreads = Math.ceil(gThreads * 1.2) + 1;\n            }\n        } catch {\n            return calcBatchFallback(ns, host, hackPct);\n        }\n    } else {\n        hackTime = ns.getHackTime(host);\n        growTime = ns.getGrowTime(host);\n        weakenTime = ns.getWeakenTime(host);\n        const result = calcBatchFallback(ns, host, hackPct);\n        if (!result) return null;\n        return { ...result, hackTime, growTime, weakenTime };\n    }\n\n    const w1Threads = Math.max(1, Math.ceil(hThreads * 0.002 / 0.05));\n    const w2Threads = Math.max(1, Math.ceil(gThreads * 0.004 / 0.05));\n\n    return { hThreads, w1Threads, gThreads, w2Threads, hackTime, growTime, weakenTime };\n}\n\nfunction calcBatchFallback(ns, host, hackPct) {\n    const hackAmt = ns.hackAnalyze(host);\n    if (hackAmt <= 0) return null;\n    const hThreads = Math.max(1, Math.floor(hackPct / hackAmt));\n    const stolen = Math.min(0.99, hackAmt * hThreads);\n    const growRatio = 1 / (1 - stolen);\n    const gThreads = Math.ceil(ns.growthAnalyze(host, growRatio));\n    const w1Threads = Math.max(1, Math.ceil(hThreads * 0.002 / 0.05));\n    const w2Threads = Math.max(1, Math.ceil(gThreads * 0.004 / 0.05));\n\n    return {\n        hThreads, w1Threads, gThreads, w2Threads,\n        hackTime: ns.getHackTime(host),\n        growTime: ns.getGrowTime(host),\n        weakenTime: ns.getWeakenTime(host),\n    };\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// DEPLOY\n// ═══════════════════════════════════════════════════════════════════════════════\n\nfunction deployHacking(ns, S) {\n    const scored = S.rooted\n        .filter((h) => !isHacknetServer(h) &&\n            ns.getServerMaxMoney(h) > 0 &&\n            ns.getServerRequiredHackingLevel(h) <= ns.getHackingLevel())\n        .map((h) => ({ host: h, score: scoreTarget(ns, h, S.hasFormulas) }))\n        .filter((t) => t.score > 0)\n        .sort((a, b) => b.score - a.score)\n        .slice(0, CFG.maxTargets);\n\n    S.targets = scored;\n    const pool = getWorkerPool(ns, S);\n\n    const prepped = [], unprepped = [];\n    for (const t of scored) {\n        const money = ns.getServerMoneyAvailable(t.host);\n        const max = ns.getServerMaxMoney(t.host);\n        const sec = ns.getServerSecurityLevel(t.host);\n        const minS = ns.getServerMinSecurityLevel(t.host);\n        if (money >= max * CFG.moneyThresh && sec <= minS + CFG.secThresh) prepped.push(t);\n        else unprepped.push(t);\n    }\n\n    for (const t of unprepped) {\n        const sec = ns.getServerSecurityLevel(t.host);\n        const minS = ns.getServerMinSecurityLevel(t.host);\n        const money = ns.getServerMoneyAvailable(t.host);\n        const max = ns.getServerMaxMoney(t.host);\n\n        if (sec > minS + CFG.secThresh) {\n            spawnAcross(ns, CFG.workerW, t.host, Math.ceil((sec - minS) / 0.05), pool, 0);\n        } else if (money < max * CFG.moneyThresh) {\n            const ratio = max / Math.max(1, money);\n            const gT = Math.ceil(ns.growthAnalyze(t.host, ratio));\n            const wT = Math.ceil(gT * 0.004 / 0.05);\n            spawnAcross(ns, CFG.workerG, t.host, gT, pool, 0);\n            spawnAcross(ns, CFG.workerW, t.host, wT, pool, 0);\n        }\n    }\n\n    let totalBatches = 0;\n    const sp = CFG.spacing;\n    const minBatchRam = 1.75 * 4;\n\n    for (const t of prepped) {\n        if (totalBatches >= CFG.maxTotalBatches) break;\n\n        const batch = calcBatch(ns, t.host, CFG.hackPct, S.hasFormulas);\n        if (!batch) continue;\n\n        const { hThreads, w1Threads, gThreads, w2Threads, hackTime, growTime, weakenTime } = batch;\n        const maxByTime = Math.floor(weakenTime / (4 * sp));\n        const batchCap = Math.min(maxByTime, CFG.maxBatchesPerTgt, CFG.maxTotalBatches - totalBatches);\n\n        for (let n = 0; n < batchCap; n++) {\n            const poolFree = pool.reduce((s, w) => s + w.free, 0);\n            if (poolFree < minBatchRam) break;\n\n            const offset = n * 4 * sp;\n            const hDelay = Math.max(0, weakenTime - hackTime - sp + offset);\n            const w1Delay = offset;\n            const gDelay = Math.max(0, weakenTime - growTime + sp + offset);\n            const w2Delay = 2 * sp + offset;\n\n            const h = spawnAcross(ns, CFG.workerH, t.host, hThreads, pool, hDelay);\n            const w1 = spawnAcross(ns, CFG.workerW, t.host, w1Threads, pool, w1Delay);\n            const g = spawnAcross(ns, CFG.workerG, t.host, gThreads, pool, gDelay);\n            const w2 = spawnAcross(ns, CFG.workerW, t.host, w2Threads, pool, w2Delay);\n\n            if (h === 0 && w1 === 0 && g === 0 && w2 === 0) break;\n            totalBatches++;\n        }\n    }\n\n    S.batchesLast = totalBatches;\n}\n\n// ═══════════════════════════════════════════════════════════════════════════════\n// STATUS\n// ═══════════════════════════════════════════════════════════════════════════════\n\nfunction showStatus(ns, S) {\n    const player = ns.getPlayer();\n    const money = ns.getServerMoneyAvailable(\"home\");\n    const pool = getWorkerPool(ns, S);\n    const freeRam = pool.reduce((s, w) => s + w.free, 0);\n    const totalRam = pool.reduce((s, w) => s + ns.getServerMaxRam(w.host), 0);\n\n    ns.clearLog();\n    ns.print(\"┌────────────────────────────────────────────────┐\");\n    ns.print(`│  ⚡ HACK MODULE  ${new Date().toLocaleTimeString().padStart(26)}│`);\n    ns.print(\"├────────────────────────────────────────────────┤\");\n    ns.print(`│ 💰 $${ns.format.number(money).padEnd(16)} 🧠 Hack: ${player.skills.hacking}`);\n    ns.print(`│ 📐 Formulas: ${S.hasFormulas ? \"yes\" : \"no\"}  🎯 Targets: ${S.targets.length}`);\n    ns.print(`│ 💾 ${ns.format.ram(freeRam)} free / ${ns.format.ram(totalRam)} (${pool.length} hosts)`);\n    ns.print(`│ 🚀 Batches launched: ${S.batchesLast}`);\n\n    const show = Math.min(S.targets.length, 6);\n    for (let i = 0; i < show; i++) {\n        const t = S.targets[i];\n        const m = ns.getServerMoneyAvailable(t.host);\n        const mx = ns.getServerMaxMoney(t.host);\n        const pct = mx > 0 ? (m / mx * 100).toFixed(0) : \"0\";\n        const sec = ns.getServerSecurityLevel(t.host);\n        const min = ns.getServerMinSecurityLevel(t.host);\n        ns.print(`│ ${t.host.padEnd(20)} ${pct.padStart(3)}%  sec ${sec.toFixed(1)}/${min.toFixed(1)}`);\n    }\n    if (S.targets.length > show) ns.print(`│ ... +${S.targets.length - show} more`);\n    ns.print(\"└────────────────────────────────────────────────┘\");\n}", "w");
    ns.tprint("  /Automation/modules/hack.js");
    ns.write("/Automation/modules/hacknet.js", "/** @param {NS} ns */\n// Purchase and upgrade hacknet nodes (or hacknet servers in BN9).\n\nimport { budget } from \"/Automation/lib/shared.js\";\n\nconst HASH_SELL = \"Sell for Money\";\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n\n    const spend = budget(ns, 0.1, 1e6);\n    if (spend <= 0) return;\n\n    const numNodes = ns.hacknet.numNodes();\n    const maxNodes = ns.hacknet.maxNumNodes();\n    const isServer = numNodes > 0 && ns.hacknet.getNodeStats(0).hashCapacity !== undefined;\n\n    if (isServer) spendHashes(ns);\n\n    if (numNodes < maxNodes) {\n        const cost = ns.hacknet.getPurchaseNodeCost();\n        if (cost > 0 && cost <= spend && ns.hacknet.purchaseNode() >= 0) return;\n    }\n\n    const upgrade = pickUpgrade(ns, spend, isServer);\n    if (upgrade) upgrade.fn(upgrade.index, upgrade.n);\n}\n\nfunction spendHashes(ns) {\n    try {\n        const upgrades = ns.hacknet.getHashUpgrades();\n        if (!upgrades.includes(HASH_SELL)) return;\n\n        const cost = ns.hacknet.hashCost(HASH_SELL, 1);\n        if (!Number.isFinite(cost) || cost <= 0) return;\n        if (ns.hacknet.numHashes() < cost) return;\n\n        ns.hacknet.spendHashes(HASH_SELL, \"\", 1);\n    } catch {\n        /* hash API unavailable */\n    }\n}\n\nfunction pickUpgrade(ns, budget, isServer) {\n    const actions = [\n        { name: \"level\", cost: (i, n) => ns.hacknet.getLevelUpgradeCost(i, n), fn: ns.hacknet.upgradeLevel.bind(ns.hacknet) },\n        { name: \"ram\", cost: (i, n) => ns.hacknet.getRamUpgradeCost(i, n), fn: ns.hacknet.upgradeRam.bind(ns.hacknet) },\n        { name: \"core\", cost: (i, n) => ns.hacknet.getCoreUpgradeCost(i, n), fn: ns.hacknet.upgradeCore.bind(ns.hacknet) },\n    ];\n\n    if (isServer) {\n        actions.push({\n            name: \"cache\",\n            cost: (i, n) => ns.hacknet.getCacheUpgradeCost(i, n),\n            fn: ns.hacknet.upgradeCache.bind(ns.hacknet),\n        });\n    }\n\n    let best = null;\n    const numNodes = ns.hacknet.numNodes();\n\n    for (let i = 0; i < numNodes; i++) {\n        const stats = ns.hacknet.getNodeStats(i);\n        for (const action of actions) {\n            const cost = action.cost(i, 1);\n            if (!Number.isFinite(cost) || cost <= 0 || cost > budget) continue;\n            const score = stats.production / cost;\n            if (!best || score > best.score) {\n                best = { index: i, n: 1, fn: action.fn, score, cost };\n            }\n        }\n    }\n\n    return best;\n}", "w");
    ns.tprint("  /Automation/modules/hacknet.js");
    ns.write("/Automation/modules/home.js", "/** @param {NS} ns */\n// Upgrade home RAM and CPU cores when affordable (requires singularity API).\n\nimport { budget, singularityReady } from \"/Automation/lib/shared.js\";\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n\n    const spend = budget(ns, 0.2, 1e6);\n    if (spend <= 0) return;\n\n    const ramCost = ns.singularity.getUpgradeHomeRamCost();\n    if (ramCost > 0 && ramCost <= spend) {\n        if (ns.singularity.upgradeHomeRam()) return;\n    }\n\n    const coreCost = ns.singularity.getUpgradeHomeCoresCost();\n    if (coreCost > 0 && coreCost <= spend) {\n        ns.singularity.upgradeHomeCores();\n    }\n}", "w");
    ns.tprint("  /Automation/modules/home.js");
    ns.write("/Automation/modules/infra.js", "/** @param {NS} ns */\n// Purchase and upgrade cloud servers for worker RAM.\n\nimport { budget } from \"/Automation/lib/shared.js\";\n\nconst PREFIX = \"pserv-\";\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n\n    const spend = budget(ns, 0.15, 2e6);\n    if (spend <= 0) return;\n\n    const names = ns.cloud.getServerNames();\n    const limit = ns.cloud.getServerLimit();\n    const ramCap = Math.min(ns.cloud.getRamLimit(), 1 << 20);\n\n    if (names.length < limit) {\n        const ram = bestAffordableRam(ns, spend, ramCap);\n        if (ram > 0) {\n            const host = ns.cloud.purchaseServer(PREFIX, ram);\n            if (host) return;\n        }\n    }\n\n    let target = null;\n    let targetRam = 0;\n    for (const host of names) {\n        const current = ns.getServerMaxRam(host);\n        const next = nextPowerOfTwo(current);\n        if (next > ramCap || next <= current) continue;\n        const cost = ns.cloud.getServerUpgradeCost(host, next);\n        if (!Number.isFinite(cost) || cost <= 0 || cost > spend) continue;\n        if (!target || current < ns.getServerMaxRam(target)) {\n            target = host;\n            targetRam = next;\n        }\n    }\n\n    if (target) ns.cloud.upgradeServer(target, targetRam);\n}\n\nfunction bestAffordableRam(ns, budget, ramCap) {\n    let best = 0;\n    for (let ram = 2; ram <= ramCap; ram *= 2) {\n        const cost = ns.cloud.getServerCost(ram);\n        if (!Number.isFinite(cost) || cost <= 0 || cost > budget) break;\n        best = ram;\n    }\n    return best;\n}\n\nfunction nextPowerOfTwo(n) {\n    if (n < 2) return 2;\n    let p = 2;\n    while (p <= n) p *= 2;\n    return p;\n}", "w");
    ns.tprint("  /Automation/modules/infra.js");
    ns.write("/Automation/modules/install.js", "/** @param {NS} ns */\n// Install purchased augmentations and restart the brain after reset.\n\nimport { singularityReady } from \"/Automation/lib/shared.js\";\n\nconst BRAIN = \"/Automation/brain.js\";\nconst MIN_BATCH = 5;\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n\n    const queued = ns.singularity.getOwnedAugmentations(true);\n    if (queued.length === 0) return;\n\n    const hasNfg = queued.includes(\"NeuroFlux Governor\");\n    if (!hasNfg && queued.length < MIN_BATCH) return;\n\n    ns.singularity.installAugmentations(BRAIN);\n}", "w");
    ns.tprint("  /Automation/modules/install.js");
    ns.write("/Automation/modules/programs.js", "/** @param {NS} ns */\n// Purchase darkweb programs in priority order (port crackers first).\n\nimport { budget, singularityReady } from \"/Automation/lib/shared.js\";\n\nconst PROGRAM_ORDER = [\n    \"BruteSSH.exe\",\n    \"FTPCrack.exe\",\n    \"relaySMTP.exe\",\n    \"HTTPWorm.exe\",\n    \"SQLInject.exe\",\n    \"AutoLink.exe\",\n    \"ServerProfiler.exe\",\n    \"DeepscanV1.exe\",\n    \"DeepscanV2.exe\",\n    \"DeepscanV3.exe\",\n    \"NPC.exe\",\n    \"InvAug.exe\",\n    \"DataInc.exe\",\n    \"BitFlume.exe\",\n];\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n\n    if (!ns.hasTorRouter()) {\n        const money = ns.getServerMoneyAvailable(\"home\");\n        if (money > 1e6) ns.singularity.purchaseTor();\n        return;\n    }\n\n    const spend = budget(ns, 0.15, 5e5);\n    if (spend <= 0) return;\n\n    for (const program of PROGRAM_ORDER) {\n        if (ns.fileExists(program, \"home\")) continue;\n\n        const cost = ns.singularity.getDarkwebProgramCost(program);\n        if (!Number.isFinite(cost) || cost <= 0 || cost > spend) continue;\n\n        if (ns.singularity.purchaseProgram(program)) return;\n    }\n}", "w");
    ns.tprint("  /Automation/modules/programs.js");
    ns.write("/Automation/modules/sleeves.js", "/** @param {NS} ns */\n// Manage sleeves: buy, memory, shock recovery, university study (SF10+).\n\nimport { budget, hasSf } from \"/Automation/lib/shared.js\";\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!hasSf(ns, 10, 1)) return;\n\n    const money = budget(ns, 0.2, 2e6);\n\n    if (ns.sleeve.getNumSleeves() < 8) {\n        const cost = ns.sleeve.getSleeveCost();\n        if (money > 0 && cost > 0 && cost <= money && ns.sleeve.purchaseSleeve()) return;\n    }\n\n    const count = ns.sleeve.getNumSleeves();\n    for (let i = 0; i < count; i++) {\n        const sleeve = ns.sleeve.getSleeve(i);\n        const task = ns.sleeve.getTask(i);\n\n        if (sleeve.shock > 0) {\n            if (task?.type !== \"RECOVERY\") ns.sleeve.setToShockRecovery(i);\n            continue;\n        }\n\n        if (sleeve.sync < 100 && task?.type !== \"SYNCHRO\") {\n            ns.sleeve.setToSynchronize(i);\n            continue;\n        }\n\n        if (task?.type === \"CLASS\") continue;\n\n        ns.sleeve.setToUniversityCourse(i, \"Rothman University\", \"Algorithms\");\n    }\n\n    if (money <= 0) return;\n    for (let i = 0; i < count; i++) {\n        const cost = ns.sleeve.getMemoryUpgradeCost(i, 1);\n        if (cost > 0 && cost <= money && ns.sleeve.upgradeMemory(i, 1)) return;\n    }\n}", "w");
    ns.tprint("  /Automation/modules/sleeves.js");
    ns.write("/Automation/modules/study.js", "/** @param {NS} ns */\n// Study at university when idle and hacking level is below target.\n\nimport { singularityReady } from \"/Automation/lib/shared.js\";\n\nconst TARGET_HACK = 150;\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    if (!singularityReady(ns)) return;\n    if (ns.getHackingLevel() >= TARGET_HACK) return;\n\n    const work = ns.singularity.getCurrentWork();\n    if (work) return;\n\n    ns.singularity.universityCourse(\"Rothman University\", \"Algorithms\", false);\n}", "w");
    ns.tprint("  /Automation/modules/study.js");
    ns.write("/Automation/modules/work.js", "/** @param {NS} ns */\n// Maintain faction reputation work toward augment purchases.\n\nimport { memberFactions, singularityReady } from \"/Automation/lib/shared.js\";\n\nconst LOOP_MS = 30000;\n\nexport async function main(ns) {\n    ns.disableLog(\"ALL\");\n    ns.clearLog();\n\n    while (true) {\n        if (singularityReady(ns)) maintainWork(ns);\n        await ns.sleep(LOOP_MS);\n    }\n}\n\nfunction maintainWork(ns) {\n    const current = ns.singularity.getCurrentWork();\n    if (current && current.type === \"FACTION\") {\n        const factions = memberFactions(ns);\n        if (factions.includes(current.factionName)) return;\n    }\n\n    const target = pickFaction(ns);\n    if (!target) return;\n\n    const types = ns.singularity.getFactionWorkTypes(target.faction);\n    const workType = pickWorkType(types);\n    if (!workType) return;\n\n    ns.singularity.workForFaction(target.faction, workType, false);\n}\n\nfunction pickFaction(ns) {\n    const owned = new Set(ns.singularity.getOwnedAugmentations());\n    const purchased = new Set(ns.singularity.getOwnedAugmentations(true));\n    let best = null;\n\n    for (const faction of memberFactions(ns)) {\n        const augs = ns.singularity.getAugmentationsFromFaction(faction);\n        for (const aug of augs) {\n            if (aug === \"NeuroFlux Governor\") continue;\n            if (owned.has(aug) || purchased.has(aug)) continue;\n            if (!prereqsMet(ns, aug, owned, purchased)) continue;\n\n            const rep = ns.singularity.getFactionRep(faction);\n            const need = ns.singularity.getAugmentationRepReq(aug);\n            if (rep >= need) continue;\n\n            const deficit = need - rep;\n            const stats = ns.singularity.getAugmentationStats(aug);\n            const value = augValue(stats);\n            const score = value / Math.max(1, deficit);\n            if (!best || score > best.score) {\n                best = { faction, aug, score, deficit };\n            }\n        }\n    }\n\n    return best;\n}\n\nfunction prereqsMet(ns, aug, owned, purchased) {\n    for (const req of ns.singularity.getAugmentationPrereq(aug)) {\n        if (!owned.has(req) && !purchased.has(req)) return false;\n    }\n    return true;\n}\n\nfunction augValue(stats) {\n    return (stats.hacking ?? 1) *\n        (stats.hacking_exp ?? 1) *\n        (stats.hacking_chance ?? 1) *\n        (stats.hacking_speed ?? 1) *\n        (stats.hacking_money ?? 1) *\n        (stats.faction_rep ?? 1) *\n        (stats.faction_work ?? 1);\n}\n\nfunction pickWorkType(types) {\n    if (!types || types.length === 0) return null;\n    if (types.includes(\"hacking\")) return \"hacking\";\n    if (types.includes(\"field\")) return \"field\";\n    if (types.includes(\"security\")) return \"security\";\n    return types[0];\n}", "w");
    ns.tprint("  /Automation/modules/work.js");
